Rules.InvariantScript:
// 1. Reset de variáveis de contexto
UpdateContext({
    var_visibleDetalhes: false,
    var_mapSelect: ""
});

// 2. Carrega CCI com veículo vinculado
//    → Filter antes do Sort: reduz o conjunto antes de ordenar
ClearCollect(
    col_dadosCCI,
    AddColumns(
        SortByColumns(
            Filter(
                'tbl_CHECK-LIST-ALL-ITENS',
                (Modulo = "Check-list CCI" Or Modulo = "Check-list CRS") And Status.Value = "Em Atendimento"
            ),
            "ID",
            SortOrder.Descending
        ),
        VEICULO,
        LookUp(
            'tbl_CHECK-LIST-VEICULO-CCI',
            ID_FORMS = ID_CheckList,
            'IDENTIFICAÇÃO DO VEÍCULO'
        )
    )
);

// 3. Pré-carrega ocorrências "Baixa do CCI" abertas UMA única vez
//    → Elimina N consultas à fonte dentro do loop original
ClearCollect(
    col_baixaCCIAberta,
    Filter(
        tbl_ReaOcorrencias,
        (Tipo_ocorrencia.Value = "Baixa do CCI" Or Tipo_ocorrencia.Value = "Baixa do CRS") And Status.Value = "Aberto"
    )
);

// 4. Monta o painel já com o status calculado via AddColumns
//    → Substitui o ForAll + Patch (N operações) por uma única passagem em memória
ClearCollect(
    col_painelOperacionalVeiculos,
    AddColumns(
        tbl_gestaoVeiculosRea,
        statusPainel,
        With(
            {
                _temCCI: CountRows(
                    Filter(col_dadosCCI, VEICULO = identificacao)
                ) > 0,
                _temBaixaCCI: CountRows(
                    Filter(col_baixaCCIAberta, Veiculo_identificacao = identificacao)
                ) > 0
            },
            If(
                _temBaixaCCI, "Crítico",
                _temCCI,     "Média",
                             "Operacional"
            )
        )
    )
)

// 1. Reset de variáveis
UpdateContext(
    {
        var_visibleDetalhes: false,
        var_mapSelect: ""
    }
);
// 2. Carrega CCI com veículo vinculado
ClearCollect(
    col_dadosCCI,
    AddColumns(
        Filter(
            'tbl_CHECK-LIST-ALL-ITENS',
            Modulo = "Check-list CCI" And Status.Value = "Em Atendimento"
        ),
        VEICULO,
        LookUp(
            'tbl_CHECK-LIST-VEICULO-CCI',
            ID_FORMS = ID_CheckList,
            'IDENTIFICAÇÃO DO VEÍCULO'
        )
    )
);
// 3. Pré-carrega ocorrências abertas UMA única vez
//    → elimina N queries a tbl_ReaOcorrencias no loop abaixo
ClearCollect(
    col_baixaCCIAberta,
    Filter(
        tbl_ReaOcorrencias,
        (Tipo_ocorrencia.Value = "Baixa do CCI" Or Tipo_ocorrencia.Value = "Baixa do CRS") And Status.Value = "Aberto"
    )
);
// 4. Patcha a collection em memória — zero queries ao Dataverse no loop
ForAll(
    col_painelOperacionalVeiculos As _v,
    Patch(
        col_painelOperacionalVeiculos,
        _v,
        {
            statusPainel: With(
                {
                    _temCCI: CountRows(
                        Filter(
                            col_dadosCCI,
                            VEICULO = _v.identificacao
                        )
                    ) > 0,
                    _temBaixaCCI: CountRows(
                        Filter(
                            col_baixaCCIAberta,
                            Veiculo_identificacao = _v.identificacao
                        )
                    ) > 0
                },
                If(
                    _temBaixaCCI,
                    "Crítico",
                    _temCCI,
                    "Média",
                    "Operacional"
                )
            )
        }
    )
)

UpdateContext(
    {
        var_visibleDetalhes: true,
        var_itensDetalhes: Filter(
            col_dadosCCI,
            VEICULO = ThisItem.identificacao
        ),
        var_baixaCCI: First(
            Sort(
            Filter(
                tbl_ReaOcorrencias,

               (Tipo_ocorrencia.Value = "Baixa do CCI" Or Tipo_ocorrencia.Value = "Baixa do CRS")  And Status.Value = "Aberto" And Veiculo_identificacao = ThisItem.identificacao
            ), ID, SortOrder.Descending)
        ),
        var_cciDados: ThisItem
    }
)

