Rules.InvariantScript:
"<div style='
    display:flex;
    align-items:center;
    justify-content:space-between;
    padding:10px 16px;
    border-radius:0px;
  /*background-color:rgba(255,255,255,0.07);
    border:1px solid rgba(255,255,255,0.08);*/
'>
    <div style='display:flex; align-items:center; gap:10px;'>
        <span style='font-size:16px; color:rgba(160,160,200,0.7);'>&#128295;</span>
        <span style='
            font-size:11px;
            font-weight:700;
            color:rgba(180,185,220,0.85);
            letter-spacing:1.2px;
            text-transform:uppercase;
        '>Não Conformidades Abertas</span>
    </div>

    <span style='
        font-size:11px;
        font-weight:600;
        color:#e8e8f0;
        background-color:rgba(0,0,0,0.35);
        border:1px solid rgba(255,255,255,0.10);
        padding:3px 10px;
        border-radius:6px;
        white-space:nowrap;
    '>"&Gallery5_1.AllItemsCount&" Registros</span>
</div>"

"<div style='
    display:flex;
    flex-direction:column;
    border-radius:12px;
    background-color:rgba(255,255,255,0.07);
    border:1px solid rgba(255,255,255,0.10);
    font-family:Segoe UI,sans-serif;
    overflow:hidden;
'>
    <div style='
        display:flex;
        align-items:center;
        justify-content:center;
        gap:10px;
        padding:14px 20px;
        background-color:rgba(204,34,0,0.15);
        border-bottom:1px solid rgba(255,80,50,0.25);
    '>
        <span style='font-size:18px; color:#ff4444;'>&#9888;</span>
        <span style='font-size:13px; font-weight:700; color:#ff6b6b; letter-spacing:0.5px;'>BAIXA DO CCI/CRS</span>
        <span style='
            font-size:11px;
            font-weight:700;
            color:#ff4444;
            background-color:rgba(255,68,68,0.15);
            border:1px solid rgba(255,68,68,0.3);
            padding:2px 10px;
            border-radius:5px;
        '>" & var_baixaCCI.Protocolo & "</span>
    </div>

    <div style='display:flex; flex-direction:column; gap:12px; padding:18px 20px;'>

        <div style='display:flex; gap:8px; align-items:flex-start;'>
            <span style='font-size:10px; font-weight:700; color:rgba(180,185,220,0.6); letter-spacing:0.8px; white-space:nowrap; padding-top:1px;'>AEROPORTO</span>
            <span style='font-size:12px; color:#e8e8f0; font-weight:600;'>" & var_baixaCCI.IATA & " — " & var_baixaCCI.Aeroporto & "</span>
        </div>

        <div style='width:100%; height:1px; background-color:rgba(255,255,255,0.07);'></div>

        <div style='display:flex; gap:8px; align-items:flex-start;'>
            <span style='font-size:10px; font-weight:700; color:rgba(180,185,220,0.6); letter-spacing:0.8px; white-space:nowrap; padding-top:1px;'>DATA</span>
            <span style='font-size:12px; color:#e8e8f0;'>" & var_baixaCCI.Data_inico & " &nbsp;&#183;&nbsp; " & var_baixaCCI.Hora_inicio & "</span>
        </div>

        <div style='width:100%; height:1px; background-color:rgba(255,255,255,0.07);'></div>

        <div style='display:flex; gap:8px; align-items:flex-start;'>
            <span style='font-size:10px; font-weight:700; color:rgba(180,185,220,0.6); letter-spacing:0.8px; white-space:nowrap; padding-top:1px;'>DESCRIÇÃO</span>
            <span style='font-size:12px; color:#e8e8f0; line-height:1.6;'>" & var_baixaCCI.Descricao_ocorrencia & "</span>
        </div>

        <div style='width:100%; height:1px; background-color:rgba(255,255,255,0.07);'></div>

        <div style='display:flex; gap:8px; align-items:flex-start;'>
            <span style='font-size:10px; font-weight:700; color:rgba(180,185,220,0.6); letter-spacing:0.8px; white-space:nowrap; padding-top:1px;'>AÇÃO</span>
            <span style='font-size:12px; color:#e8e8f0; line-height:1.6;'>" & If(IsBlank(var_baixaCCI.Acao_tomada), "<span style='color:rgba(180,185,220,0.4); font-style:italic;'>N/A</span>", var_baixaCCI.Acao_tomada) & "</span>
        </div>

        <div style='width:100%; height:1px; background-color:rgba(255,255,255,0.07);'></div>

        <div style='display:flex; justify-content:space-between; align-items:center;'>
            <div style='display:flex; gap:8px; align-items:center;'>
                <span style='font-size:10px; font-weight:700; color:rgba(180,185,220,0.6); letter-spacing:0.8px;'>CRIADO POR</span>
                <span style='font-size:12px; color:#e8e8f0;'>" & var_baixaCCI.'Criado por'.DisplayName & "</span>
            </div>
            <span style='
                font-size:10px;
                font-weight:700;
                color:#e8e8f0;
                background-color:rgba(255,255,255,0.08);
                border:1px solid rgba(255,255,255,0.15);
                padding:3px 10px;
                border-radius:5px;
                letter-spacing:0.5px;
            '>" & var_baixaCCI.Status.Value & "</span>
        </div>

    </div>
</div>"

With(
    {
        corBadge: Switch(
            ThisItem.Criticidade.Value,
            "BAIXA",   "background-color:#1a7a3c; color:#fff;",
            "MÉDIA",   "background-color:#cc7700; color:#fff;",
            "CRÍTICO", "background-color:#cc2200; color:#fff;",
                       "background-color:#1a7a3c; color:#fff;"
        )
    },
    "<div style='
        display:flex;
        flex-direction:column;
        gap:4px;
        padding:8px 10px;
        border-radius:12px;
        background-color:rgba(255,255,255,0.07);
        border:1px solid rgba(255,255,255,0.10);
        font-family:Segoe UI,sans-serif;
    '>
        <div style='display:flex; justify-content:space-between; align-items:center;'>
            <span style='font-size:11px; color:rgba(180,185,220,0.75);'>
                ITEM: <span style='color:#e8e8f0; font-weight:700;'>" & ThisItem.Item & "</span>
            </span>
            <span style='font-size:11px; color:rgba(180,185,220,0.6);'>" & Text(ThisItem.Criado, "dd/mm/yyyy hh:mm") & "</span>
        </div>

        <div style='font-size:10px; color:rgba(160,165,200,0.6); letter-spacing:0.3px;'>
            ID: " & ThisItem.ID_CheckList & " &bull; TICKET: " & ThisItem.'Número do chamado' & "
        </div>

        <div style='font-size:13px; font-weight:600; color:#e8e8f0; line-height:1.5;'>
            " & ThisItem.Descrição & "
        </div>

        <div style='display:flex; justify-content:space-between; align-items:center; margin-top:2px;'>
            <span style='font-size:11px; color:rgba(100,210,160,0.9);'>
                &#10549; Status: " & ThisItem.Status.Value & "
            </span>
            <span style='
                font-size:10px;
                font-weight:700;
                padding:2px 10px;
                border-radius:5px;
                letter-spacing:1px;
                " & corBadge & "
            '>" & Coalesce( ThisItem.Criticidade.Value, "BAIXA") & "</span>
        </div>
    </div>"
)

